(
    // Small map for tests: uses every legend entry. Not a real chapter map.
    name: "Test Field",
    legend: {
        '.': "plain",
        ':': "road",
        'T': "forest",
        '%': "thicket",
        '^': "mountain",
        'A': "peak",
        '~': "water",
        'S': "sea",
        '#': "wall",
        '+': "door",
        '_': "floor",
        'F': "fort",
        '=': "bridge",
    },
    // One of each tile feature, on the plain row y = 3.
    features: {
        (5, 3): Shop(kind: Armoury, stock: ["iron_sword", "leather_vest", "speed_ring"]),
        (6, 3): Shop(kind: Vendor, stock: ["potion"]),
        (7, 3): Shop(kind: Blacksmith, stock: []),
        (8, 3): Chest(Gold(500)),
        (9, 3): Chest(Item("elixir")),
    },
)
